"""Original HHS and hypoglycemia questions completing Endocrine chapter two."""
from create_diabetic_emergencies import rows,q,CR,GL,HY
from qbank_authoring import ref,finalize
PB=ref('Society for Endocrinology: Post-Bariatric Hypoglycaemia Guideline, 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC11046333/')
HR=ref('Endocrine Society: Management of Individuals With Diabetes at High Risk for Hypoglycemia, 2023','https://academic.oup.com/jcem/article/108/3/529/6880627')
OC=ref('Queensland Poisons Information Centre: Octreotide for Sulfonylurea Toxicity','https://www.poisonsinfo.health.qld.gov.au/for-health-professionals/antidote-stocking-recommendations/octreotide')
q('Which set best matches the 2024 consensus HHS criteria?', 'Glucose at least 600 mg/dL, hyperosmolality, no significant ketonemia and no significant acidosis',[
 ('Glucose 250 with beta-hydroxybutyrate 6 and pH 7.1','This is a DKA pattern.'),('Any glucose above 200 without osmolality assessment','This is not sufficient for HHS.'),('Normal glucose with isolated high urea','Total osmolality can rise from urea without this hyperglycemic syndrome.')],
 'HHS has four required diagnostic components', '**Hyperosmolality means effective osmolality above 300 or total osmolality above 320 mOsm/kg.**',['Beta-hydroxybutyrate should be below 3 mmol/L for uncomplicated HHS.','The absence-of-acidosis criterion uses pH at least 7.3 and bicarbonate at least 15 mmol/L.'], '**Look for mixed DKA/HHS when ketosis or acidosis is substantial.**',['Assess dehydration, cognition and triggers.','Do not require coma for the diagnosis.'],[['Glucose','At least 600 mg/dL'],['Osmolality','Effective above 300 or total above 320'],['Ketones/acidosis','Not significant in pure HHS']],[CR])
q('Sodium is 150 mmol/L and glucose 900 mg/dL. What is the calculated effective osmolality excluding urea?', '350 mOsm/kg',[
 ('300 mOsm/kg','This omits the glucose contribution.'),('325 mOsm/kg','The glucose contribution is 50, not 25.'),('400 mOsm/kg','This overestimates the specified calculation.')],
 'Use compatible units in the osmolality formula', '**Effective osmolality = 2 × sodium + glucose/18 when glucose is in mg/dL.**',['Here 300 + 50 equals 350.','Total calculated osmolality adds the urea contribution.'], '**Interpret with symptoms and serial values.**',['A single estimate does not define the entire fluid plan.','Measured sodium is used in this effective-osmolality calculation.'],[['Sodium contribution','300'],['Glucose contribution','50'],['Effective osmolality','350']],[CR])
q('An adult has glucose 780 mg/dL, effective osmolality 340, beta-hydroxybutyrate 5 mmol/L and pH 7.18. Which treatment pathway is appropriate?', 'Treat as mixed DKA/HHS with DKA-intensity insulin and careful hyperosmolar fluid management',[
 ('Pure HHS with no ketoacidosis treatment','Significant ketonemia and acidosis are present.'),('Starvation ketosis without a hyperglycemic emergency','The severe hyperglycemia and hyperosmolality contradict that limited label.'),('Immediate normalization of osmolality regardless of rate','Rapid osmotic shifts can be hazardous.')],
 'The syndromes can overlap', '**Significant ketonemia or acidosis changes the insulin approach.**',['The consensus uses an IV insulin rate of about 0.1 units/kg/hour for mixed DKA/HHS.','Fluid and potassium management still require individualization.'], '**Manage both the ketotic and hyperosmolar risks.**',['Use frequent metabolic and neurological checks.','Treat precipitating infection, ischemia or delivery failure.'],[['Hyperosmolar component','Severe glucose and osmolality'],['Ketotic component','Ketones plus acidosis'],['Pathway','Mixed-crisis treatment']],[CR],'clinical_scenario')
q('During HHS fluid treatment, glucose falls and measured sodium rises modestly while osmolality is declining appropriately. What does this sodium rise usually mean?', 'Water is shifting back into cells as glucose falls; the rise alone does not mandate hypotonic fluid',[
 ('Treatment has necessarily failed','The expected transcellular shift can raise sodium.'),('All isotonic fluid must be stopped immediately regardless of perfusion','Fluid decisions depend on osmolality and circulation.'),('A sodium rise is impossible unless new salt poisoning occurred','Glucose correction itself can explain it.')],
 'Track tonicity rather than one electrolyte in isolation', '**A glucose fall of 100 mg/dL commonly raises sodium by about 1.6 mmol/L in the consensus description.**',['The relation is approximate.','A declining osmolality and improving circulation guide interpretation.'], '**Reassess fluid balance and the full trend.**',['Hypotonic saline is considered when osmolality is not declining despite adequate appropriate treatment.','Do not chase a sodium change without evaluating its mechanism.'],[['Glucose falls','Water returns intracellularly'],['Sodium','May rise'],['Main trend','Osmolality plus clinical response']],[CR],'clinical_scenario')
q('What rate of osmolality decline is generally targeted during adult HHS treatment?', 'About 3–8 mOsm/kg/hour',[
 ('At least 20–30 mOsm/kg/hour','This is excessively rapid.'),('No decline should occur for the first 24 hours','The hyperosmolar state requires controlled correction.'),('A fixed rate unrelated to neurological status or glucose','Clinical and biochemical reassessment remains essential.')],
 'Controlled osmotic correction reduces neurological risk', '**The 2024 consensus recommends avoiding an osmolality fall faster than about 3–8 mOsm/kg/hour.**',['Glucose decline should generally not exceed about 90–120 mg/dL/hour.','Sodium reduction is also limited, commonly no more than 10 mmol/L in 24 hours.'], '**Use serial osmolality and neurological assessment.**',['Older adults and comorbidity need cautious fluid planning.','Avoid assuming a faster glucose fall is always better.'],[['Osmolality','3–8 mOsm/kg/hour'],['Glucose','Avoid excessive hourly fall'],['Monitoring','Neurological and metabolic trends']],[CR])
q('Which combination supports HHS resolution?', 'Osmolality below 300, improved cognition and volume status, adequate urine output and corrected marked hyperglycemia',[
 ('Glucose below 250 alone with persistent profound hyperosmolality','Glucose alone is insufficient.'),('A negative urine ketone strip alone','HHS is primarily a hyperosmolar rather than ketotic syndrome.'),('Normal A1C during admission','A1C is not an acute resolution criterion.')],
 'Clinical recovery must accompany biochemical improvement', '**The consensus considers urine output above 0.5 mL/kg/hour, improved cognition and glucose below 250 alongside osmolality below 300.**',['Kidney failure can require individualized interpretation of urine criteria.','Underlying triggers and complications must also be addressed.'], '**Plan ongoing insulin and preventive care.**',['Assess thrombosis risk and use appropriate inpatient prophylaxis unless contraindicated.','Ensure adequate water access and a practical discharge plan.'],[['Osmolality','Below 300'],['Clinical state','Cognition and volume improve'],['Transition','Safe ongoing treatment and support']],[CR])
q('An insulin-treated patient is confused and needs another person to administer glucagon. The recorded glucose is 58 mg/dL. Which classification applies?', 'Level 3 severe hypoglycemia',[
 ('Level 1 only because glucose is above 54','Need for assistance due to impairment defines level 3 irrespective of the measured threshold.'),('Level 2 only because every confused episode must be below 54','Level 2 is the biochemical threshold below 54; severe assistance-based events are level 3.'),('Not hypoglycemia because the value is above 50','The episode is clinically and biochemically important.')],
 'Severity is not defined by concentration alone', '**Level 3 involves altered mental or physical functioning requiring assistance.**',['Level 1 is below 70 but at least 54 mg/dL.','Level 2 is below 54 mg/dL.'], '**Reevaluate treatment after a severe event.**',['Identify timing, food, renal, activity and dosing contributors.','Provide rescue supplies and caregiver training.'],[['Level 1','54 to below 70'],['Level 2','Below 54'],['Level 3','Requires assistance because of impairment']],[GL,HR],'clinical_scenario')
q('An awake adult with diabetes has glucose 61 mg/dL and can swallow safely. What is the usual initial treatment?', 'Fast-acting glucose, commonly about 15 g, followed by rechecking in about 15 minutes',[
 ('Chocolate as the most rapid preferred treatment','Fat can slow carbohydrate absorption.'),('A large insulin correction','This worsens hypoglycemia.'),('Wait for symptoms to become severe','Treat the alert-level low promptly.')],
 'Rapid absorbable carbohydrate is the first step when swallowing is safe', '**Glucose is preferred for a quick response.**',['Repeat treatment if still low.','Some AID users may need a smaller amount according to their individualized plan.'], '**Prevent recurrence after initial recovery.**',['Review active insulin and the next meal.','If alpha-glucosidase inhibitors are used, glucose rather than sucrose is particularly important.'],[['Initial treatment','Fast-acting glucose'],['Recheck','About 15 minutes'],['After recovery','Address ongoing cause and food timing']],[GL,HR],'clinical_scenario')
q('An unconscious insulin-treated patient is hypoglycemic and cannot swallow safely. Which rescue principle is correct?', 'Give parenteral glucose when IV access is available or an appropriate glucagon rescue product, and protect the airway',[
 ('Pour a sweet drink into the mouth','This risks aspiration.'),('Wait for oral treatment to become possible','Severe hypoglycemia needs immediate rescue.'),('Glucagon removes the need for later assessment','Recurrence and the cause still require review.')],
 'The route must match consciousness and access', '**Oral carbohydrate is unsafe with impaired swallowing.**',['Ready-to-use injectable or intranasal glucagon can simplify out-of-hospital rescue.','Glucagon may be less effective with depleted glycogen stores.'], '**Continue monitoring after recovery.**',['Provide food when safe and appropriate.','Arrange emergency evaluation and regimen review as indicated.'],[['Unsafe swallowing','No oral intake'],['IV access','Parenteral glucose'],['No immediate IV','Appropriate glucagon rescue']],[GL,HR],'clinical_scenario')
q('Which triad supports investigation of a hypoglycemic disorder in a person without diabetes?', 'Compatible symptoms, documented low plasma glucose and relief when glucose is raised',[
 ('Symptoms alone after a meal without a low glucose','This does not establish a hypoglycemic disorder.'),('A single asymptomatic sensor low without confirmation','Low-range sensor accuracy and context require consideration.'),('High insulin measured during normal glucose without symptoms','Insulin must be interpreted during documented hypoglycemia.')],
 'Whipple’s triad prevents mislabeling nonspecific symptoms', '**The symptoms must coincide with genuinely low glucose.**',['A reliable laboratory sample is preferred for formal evaluation.','Preanalytical glycolysis can create spurious low values.'], '**Evaluate mechanism after confirming the syndrome.**',['Review drugs, critical illness, hormone deficiency and tumors.','Do not delay treatment of a clinically dangerous event merely to complete testing.'],[['Symptoms','Compatible with hypoglycemia'],['Measurement','Low plasma glucose'],['Response','Improves with correction']],[HY])
q('During spontaneous fasting hypoglycemia in a stable adult, which critical-sample combination best evaluates an insulin-mediated mechanism?', 'Plasma glucose, insulin, C-peptide, proinsulin, beta-hydroxybutyrate and a hypoglycemic-agent screen',[
 ('Fasting insulin measured only after glucose has normalized','This can miss inappropriate secretion during the event.'),('A1C and cholesterol alone','These do not identify the acute mechanism.'),('Pancreatic imaging before any biochemical confirmation','Incidental lesions can mislead when endogenous hyperinsulinism is unproven.')],
 'The sample must capture the physiology at the time of the low', '**Insulin should normally be suppressed during hypoglycemia.**',['C-peptide and proinsulin help distinguish endogenous from exogenous insulin.','Secretagogue screening is essential before labeling insulinoma.'], '**Obtain samples without delaying necessary rescue.**',['Assay sensitivity and insulin-analog detection vary.','Critical illness and renal function affect interpretation.'],[['Timing','During documented hypoglycemia'],['Hormones','Insulin/C-peptide/proinsulin'],['Context','Ketones and drug screen']],[HY])
q('During plasma glucose 42 mg/dL, insulin is inappropriately high, C-peptide is suppressed and the secretagogue screen is negative. Which mechanism is favored?', 'Exogenous insulin exposure',[
 ('Insulinoma','Endogenous secretion usually retains C-peptide and proinsulin.'),('Sulfonylurea exposure','This stimulates endogenous insulin and C-peptide and should be assessed with an appropriate screen.'),('Pure starvation with suppressed insulin','The insulin is inappropriately high.')],
 'C-peptide separates injected from endogenous insulin in the appropriate assay context', '**Injected insulin lacks C-peptide.**',['Insulin assays vary in their recognition of analogs.','A very low measured insulin does not exclude an analog missed by the assay.'], '**Investigate the exposure safely and without assumptions about intent.**',['Medication error and access history matter.','Treat and monitor because the effect can be prolonged.'],[['Exogenous insulin','High detected insulin/low C-peptide'],['Endogenous secretion','C-peptide retained'],['Caution','Analog assay variability']],[HY],'clinical_scenario')
q('Fasting hypoglycemia shows nonsuppressed insulin, C-peptide and proinsulin with low ketones. What is required before concluding that an insulinoma is responsible?', 'Exclude insulin secretagogue exposure with an appropriate drug screen and confirm endogenous hyperinsulinism',[
 ('A positive C-peptide by itself proves a pancreatic tumor','Sulfonylureas and meglitinides can produce the same biochemical pattern.'),('A normal CT excludes endogenous hyperinsulinism','Small insulinomas can be missed.'),('Begin localization without considering drug exposure','This risks unnecessary tumor work-up.')],
 'Biochemistry establishes a mechanism before imaging localizes a lesion', '**Insulinoma and secretagogue exposure can both preserve C-peptide.**',['Low beta-hydroxybutyrate supports insulin action.','A screen must cover relevant agents and be timed appropriately.'], '**Use supervised confirmation and then localization.**',['Consider insulin antibodies in the appropriate context.','Do not interpret a coincidental pancreatic lesion as proof.'],[['Insulinoma','Endogenous secretion, screen negative'],['Secretagogue','Similar hormones, screen positive'],['Imaging','After biochemical diagnosis']],[HY])
q('Recurrent fasting neuroglycopenic episodes are not captured spontaneously. Which investigation can document suspected fasting endogenous hyperinsulinism?', 'A supervised fast, up to 72 hours when needed, with protocolized critical sampling',[
 ('An unsupervised prolonged fast at home','This is hazardous.'),('An OGTT as the preferred fasting-hypoglycemia test','A glucose load does not reproduce the fasting physiology appropriately.'),('Immediate pancreatic surgery based only on symptoms','Biochemical confirmation is required.')],
 'Provocation must reproduce the relevant physiology safely', '**A supervised fast is stopped according to symptoms and biochemical criteria.**',['Not every patient requires the full 72 hours.','The critical sample should establish whether insulin is appropriately suppressed.'], '**Localize only after the biochemical mechanism is established.**',['Use specialist monitoring and a rescue plan.','Postprandial syndromes require a different assessment.'],[['Pattern','Fasting episodes'],['Test','Supervised fast'],['Endpoint','Protocolized symptomatic/biochemical criteria']],[HY],'clinical_scenario')
q('Two years after gastric bypass, a patient has confirmed symptomatic hypoglycemia two to three hours after meals but no fasting episodes. Which approach best matches the 2024 Society for Endocrinology guidance?', 'Confirm Whipple’s triad in the typical setting, exclude alternatives and use structured dietary management; routine OGTT or mixed-meal provocation is not recommended',[
 ('Use an OGTT as the mandatory diagnostic test','It can provoke misleading or dangerous lows and is not recommended.'),('A sensor low alone definitively establishes the diagnosis','The guideline does not recommend CGM alone for diagnosis.'),('Proceed directly to pancreatectomy before dietary assessment','This is not routine first-line management.')],
 'Post-bariatric hypoglycemia has a characteristic postprandial pattern', '**Rapid nutrient transit and exaggerated incretin-insulin responses contribute.**',['Dietetic review emphasizes controlled carbohydrate portions, low-glycemic choices and adequate protein.','Acarbose is a usual first pharmacological option when needed.'], '**Investigate atypical fasting or very early postoperative episodes separately.**',['Do not equate every dumping symptom with proven hypoglycemia.','Specialist escalation is needed when conservative treatment fails.'],[['Timing','Typically hours after meals'],['Diagnosis','Whipple’s triad and exclusions'],['Initial care','Dietetic strategy, then selected medication']],[PB],'clinical_scenario')
q('A patient taking a sulfonylurea has recurrent hypoglycemia despite repeated IV glucose. Which adjunct can suppress further insulin release?', 'Octreotide under a toxicology-guided protocol',[
 ('Additional sulfonylurea','This worsens endogenous secretion.'),('A loop diuretic as the primary antidote','This does not suppress insulin secretion.'),('Stopping glucose checks after one normal reading','Long-acting agents can cause recurrence.')],
 'Glucose alone can stimulate more insulin in secretagogue poisoning', '**Octreotide inhibits pancreatic insulin release.**',['Initial hypoglycemia still requires prompt glucose rescue.','Kidney impairment and long-acting drugs can prolong risk.'], '**Arrange appropriate observation and poison-center advice.**',['Use local dosing and monitoring guidance.','Check for accidental ingestion or medication errors without assuming intent.'],[['Exposure','Sulfonylurea'],['Recurrence mechanism','Stimulated endogenous insulin'],['Adjunct','Octreotide']],[OC],'clinical_scenario')
q('A person with long-standing type 1 diabetes has frequent asymptomatic lows. Which strategy can help reduce impaired hypoglycemia awareness?', 'Strict avoidance of further hypoglycemia with regimen review, structured education and suitable CGM alerts',[
 ('Deliberately induce more lows to train awareness','Recurrent exposure can worsen counterregulatory impairment.'),('Continue the same regimen because symptoms are absent','Absence of warning symptoms increases danger.'),('Set a lower glucose target immediately in every case','Goals may need temporary relaxation to prevent lows.')],
 'Recurrent hypoglycemia can blunt warning and counterregulatory responses', '**Avoidance can improve awareness in some individuals.**',['Autonomic neuropathy is not the only mechanism.','Exercise, alcohol, sleep and kidney disease affect risk.'], '**Use a coordinated prevention plan.**',['Provide glucagon and train close contacts.','Assess awareness periodically and address driving or work risks according to local guidance.'],[['Problem','Reduced warning symptoms'],['Intervention','Avoid lows and revise treatment'],['Support','Education, technology and rescue access']],[HR,GL],'clinical_scenario')
q('A patient without diabetes has hypoglycemia during severe sepsis with liver dysfunction and poor intake. Which evaluation priority is most appropriate?', 'Assess critical illness, substrate depletion, impaired glucose production and medication effects before assuming an insulinoma',[
 ('Every low glucose without diabetes is an insulinoma','Critical illness and organ failure are important causes.'),('Insulin must be high in all hypoglycemia','Noninsulin mechanisms can occur with appropriately suppressed insulin.'),('A normal previous A1C makes the current low harmless','An acute severe low remains dangerous.')],
 'The clinical setting determines the first branch of the differential', '**Liver failure, sepsis, malnutrition and hormone deficiency can impair glucose availability.**',['Renal dysfunction can alter drug clearance.','Adrenal insufficiency should be assessed when suggested by the presentation.'], '**Treat the low and the underlying illness together.**',['Obtain a critical sample if useful without delaying rescue.','Reserve tumor localization for a supported biochemical mechanism.'],[['Unwell patient','Critical illness and organ failure'],['Well patient','Drugs or endogenous hyperinsulinism among causes'],['Action','Rescue plus mechanism-based assessment']],[HY],'clinical_scenario')

if __name__=='__main__':finalize('Endocrine',2,'Hypoglycemia and Hyperglycemic Emergencies','endo-emergencies',rows,36)
